        Asana(id = "at_deepdog", nameRu = "Глубокая собака мордой вниз", nameEn = "Deep downward dog", pose = p(318, 255, 315, 315, 240, 240, 0, 241, 241, 0, 317, 317, 310),
            cuesRu = listOf("Голова свободно висит, по возможности касается пола.", "Поставить ногу, расслабить всё лишнее.", "Оттолкнуться основаниями ладоней и подняться на пальцы."), sanskrit = "адхо-мукха-шванасана", descriptionRu = "С выдохом опускаем голову и позволяем ей свободно повиснуть на расслабленной шее, хорошо если она коснётся пола. Плечи немного расслаблены, всё остальное как в упоре-горке. Расслабляем все мышцы, не нужные для удержания позы, и свободно дышим одну-две минуты.", descriptionEn = "On the exhale, lower the head and let it hang freely on a relaxed neck, ideally touching the floor. Shoulders slightly relaxed, everything else as in the downward plank. Relax all muscles not needed to hold the pose and breathe freely for one or two minutes.",
            figure = FigureRef("deepdog", false)),
