            figure = FigureRef("sarvonebent", true)),
        Asana(id = "at_sbridgek", nameRu = "Полумост с опорой на руки", nameEn = "Supported half bridge", pose = p(310, 0, 180, 60, 175, 265, 180, 174, 266, 180, 178, 58, 290),
