            figure = FigureRef("sbridgek", false)),
        Asana(id = "at_sbridge", nameRu = "Мост на плечах с опорой на руки", nameEn = "Supported shoulder bridge", pose = p(320, 0, 180, 60, 205, 205, 90, 206, 206, 90, 178, 58, 300),
