            figure = FigureRef("sbridgek1", true)),
        Asana(id = "at_sbridgeup_m", nameRu = "Мост на плечах, нога вверх", nameEn = "Shoulder bridge, one leg up", pose = p(320, 0, 178, 58, 206, 206, 90, 90, 90, 0, 180, 60, 300),
