            figure = FigureRef("sbridgeup", true)),
        Asana(id = "at_viparita", nameRu = "Перевёрнутая поза (випарита карани)", nameEn = "Inverted pose (viparita karani)", pose = p(315, 0, 180, 45, 90, 90, 0, 91, 91, 0, 178, 43, 315),
            cuesRu = listOf("Прыжком ноги вертикально; «ступенька» в тазу, таз и живот горизонтальны.", "Затем связку с зеркальным лотосом."), sanskrit = "випарита-карани-мудрасана", descriptionRu = "Слегка согнув ноги, разворачиваем стопы наружу; прыжком подбрасываем ноги и вытягиваем их вертикально, подошвы горизонтальны. Главное — «ступенька» в тазу: таз и живот горизонтальны, ладони поддерживают таз. Фиксацию можно держать сколь угодно долго.", descriptionEn = "Bending the legs slightly, turn the feet out; with a jump, kick the legs up and extend them vertically, soles horizontal. The key is the “step” at the pelvis: pelvis and belly horizontal, palms supporting the pelvis. The hold can be kept as long as you like.",
            figure = FigureRef("viparita", false)),
        Asana(id = "at_hala", nameRu = "Плуг", nameEn = "Plough", pose = p(290, 0, 180, 180, 335, 335, 270, 336, 336, 270, 179, 179, 275),
            cuesRu = listOf("Стопы за голову, вывернутый замок к полу, стопы дальше от головы.", "Ноги прямые, ладони в пол."), sanskrit = "халасана", descriptionRu = "Медленно опускаем прямые ноги за голову, руки — в вывернутый замок на полу. Тянем позвоночник, отодвигая стопы от головы; таз наклоняется к стопам, носки на себя.", descriptionEn = "Slowly lower the straight legs behind the head, arms in a reversed lock on the floor. Lengthen the spine by moving the feet away from the head; the pelvis tilts toward the feet, toes toward you.",
            figure = FigureRef("hala", false, hands = HandShape.LOCK)),
        Asana(id = "at_uthala", nameRu = "Вытянутый плуг", nameEn = "Extended plough", pose = p(305, 0, 180, 180, 345, 345, 280, 346, 346, 280, 179, 179, 280),
            cuesRu = listOf("Носки оттянуть, наклоном таза отодвинуть стопы ещё дальше."), sanskrit = "уттана-халасана", descriptionRu = "Продолжая ровно дышать, оттягиваем носки и наклоном таза отталкиваем стопы ещё дальше от головы.", descriptionEn = "Continuing to breathe evenly, point the toes and, by tilting the pelvis, push the feet even farther from the head.",
            figure = FigureRef("uthala", false, hands = HandShape.LOCK)),
        Asana(id = "at_shavaring", nameRu = "Расслабление на спине", nameEn = "Relaxation on the back", pose = p(0, 0, 30, 330, 180, 180, 90, 179, 179, 92, 28, 332, 0),
            cuesRu = listOf("Руки незамкнутым кольцом вокруг головы."), sanskrit = "шавасана", descriptionRu = "Медленно, позвонок за позвонком, опускаем спину на пол, руки кладём незамкнутым кольцом вокруг головы — кончики пальцев в 2–3 см друг от друга. Полное расслабление.", descriptionEn = "Slowly, vertebra by vertebra, lower the back to the floor and place the arms in an open ring around the head — fingertips 2–3 cm apart. Complete relaxation.",
            figure = FigureRef("shavaring", false)),
        Asana(id = "at_wheelprep", nameRu = "Мост: подъём", nameEn = "Bridge: rising", pose = p(330, 250, 320, 240, 210, 260, 180, 211, 261, 180, 322, 242, 290),
            cuesRu = listOf("Ладони у ушей, стопы у таза; поднять таз, спину и голову."), sanskrit = "урдхва-дханурасана", descriptionRu = "Ладони у ушей пальцами к плечам, стопы у таза; расстояние между ладонями и между стопами — ширина плеч. Растягивая тело между коленями и локтями, поднимаем таз, спину и голову.", descriptionEn = "Palms by the ears with fingers toward the shoulders, feet by the pelvis; the distance between the palms and between the feet is shoulder width. Stretching the body between the knees and elbows, lift the pelvis, back and head.",
            figure = FigureRef("wheelprep", false)),
        Asana(id = "at_wheel", nameRu = "Мост", nameEn = "Bridge", pose = p(350, 260, 300, 300, 220, 265, 180, 221, 266, 180, 302, 302, 315),
            cuesRu = listOf("Выпрямить руки и ноги; живот как столешница, пресс слегка напряжён.", "Медленный спуск в мост из стойки.", "Мягким прыжком отодвинуть стопы от кистей."), sanskrit = "урдхва-дханурасана", descriptionRu = "Выпрямляем руки и ноги. Живот — как столешница, пресс слегка напряжён и бережёт поясницу. Глубина прогиба — за счёт раскрытия груди и плеч, лопатки сведены, стопы параллельны.", descriptionEn = "Straighten the arms and legs. The belly is like a tabletop, abs slightly engaged to protect the lower back. The depth of the backbend comes from opening the chest and shoulders, shoulder blades drawn together, feet parallel.",
