        Asana(id = "at_padmafoldnam", nameRu = "Наклон в лотосе, ладони между лопаток", nameEn = "Bend in lotus, palms between the shoulder blades", pose = p(90, 270, 220, 160, 0, 176, 176, 180, 4, 4, 320, 20, 90, front = 1.0, spineScale = 0.3),
            cuesRu = listOf("Подбородок к полу.", "Сложно: правое плечо на пол за левым коленом. Беречь поясницу."), sanskrit = null, descriptionRu = "Вид спереди. Наклон в лотосе, подбородок к полу, ладони сложены между лопаток. В вариантах торс смещается вправо и влево к коленям или скручивается с плечом за колено.", descriptionEn = "Front view. Bend in lotus, chin to the floor, palms joined between the shoulder blades. In the variations, the torso shifts right and left toward the knees or twists with the shoulder past the knee.",
            figure = FigureRef("padmafoldnam", false)),
        Asana(id = "at_padmadhanu1", nameRu = "Лотосовый лук: подготовка", nameEn = "Lotus bow: preparation", pose = p(100, 110, 240, 260, 0, 178, 178, 2, 182, 178, 242, 262, 110),
            cuesRu = listOf("Ладони позади таза пальцами назад, прогнуться."), sanskrit = "падма-дханурасана", descriptionRu = "Ладони на полу позади таза пальцами назад, чуть шире плеч. Таз вперёд, плечи расправлены, грудь раскрыта.", descriptionEn = "Palms on the floor behind the pelvis, fingers back, slightly wider than the shoulders. Pelvis forward, shoulders broad, chest open.",
            figure = FigureRef("padmadhanu1", false)),
        Asana(id = "at_padmadhanu2", nameRu = "Лотосовый лук", nameEn = "Lotus bow", pose = p(160, 215, 260, 260, 20, 178, 178, 22, 182, 178, 262, 262, 178),
            cuesRu = listOf("Таз вверх, голова назад, шея вытягивается."), sanskrit = "падма-дханурасана", descriptionRu = "Отталкиваясь руками, поднимаем таз и прогибаемся, голова назад; шея вытягивается, а не ломается.", descriptionEn = "Pushing with the arms, lift the pelvis and arch, head back; the neck lengthens rather than kinks.",
            figure = FigureRef("padmadhanu2", false)),
        Asana(id = "at_lotusturtle", nameRu = "Лотосовая черепаха", nameEn = "Lotus turtle", pose = p(60, 80, 340, 60, 40, 178, 178, 42, 182, 178, 342, 62, 70),
            cuesRu = listOf("Руки сквозь лотос, сампурна-мудра; балансировать."), sanskrit = "уттана-курмасана", descriptionRu = "Руки до локтей сквозь промежутки между бёдрами и голенями, лотос прижат к животу, кисти в сампурна-мудре; балансируем на ягодицах. Вариант — обхватить лотос руками снаружи.", descriptionEn = "Arms up to the elbows through the gaps between the thighs and shins, lotus pressed to the belly, hands in sampurna mudra; balance on the buttocks. Variation: wrap the lotus with the arms from the outside.",
            figure = FigureRef("lotusturtle", false, hands = HandShape.LOCK)),
        Asana(id = "at_tola", nameRu = "Лотос на весу на ладонях", nameEn = "Lotus lifted on the palms", pose = p(90, 90, 270, 270, 15, 178, 178, 17, 182, 178, 272, 272, 90),
            cuesRu = listOf("Ладони по бокам таза."), sanskrit = null, descriptionRu = "Ладони (пальцы, кулаки) по бокам таза, поднимаемся на руках, держа лотос на весу перед собой.", descriptionEn = "Palms (fingertips, fists) at the sides of the pelvis, rise on the arms, holding the lotus suspended in front of you.",
            figure = FigureRef("tola", false)),
        Asana(id = "at_tolang", nameRu = "Уголок на руках", nameEn = "L-sit on the hands", pose = p(95, 90, 268, 268, 5, 5, 90, 6, 6, 90, 270, 270, 95),
            cuesRu = listOf("Выпрямить ноги, балансировать дольше."), sanskrit = "толангуласана", descriptionRu = "Из лотоса на весу выпрямляем ноги перед собой и балансируем на руках как можно дольше.", descriptionEn = "From the lifted lotus, straighten the legs in front of you and balance on the arms as long as possible.",
            figure = FigureRef("tolang", false)),
        Asana(id = "at_paschtw", nameRu = "Скручивание в наклоне сидя: рука вверх", nameEn = "Twist in seated bend: arm up", pose = p(12, 355, 0, 0, 0, 0, 90, 1, 1, 90, 90, 90, 6),
            cuesRu = listOf("Правой подмышкой за левое колено, левую руку вверх, взгляд на палец."), sanskrit = "паривритта-пащчимоттанасана", descriptionRu = "Из пащчимоттанасаны тянем одну руку к противоположному колену, «цепляясь» подмышкой, другую вытягиваем вверх и смотрим на её большой палец. Затем руками за стопы крест-накрест и ещё сильнее скручиваемся вдоль ног.", descriptionEn = "From Paschimottanasana, reach one arm to the opposite knee, “hooking” it with the armpit, extend the other arm up and look at its thumb. Then hold the feet crosswise and twist even more along the legs.",
            figure = FigureRef("paschtw", false)),
        Asana(id = "at_bakadho", nameRu = "Прыжок в ворону", nameEn = "Jump into crow", pose = p(335, 5, 240, 290, 328, 150, 120, 326, 148, 118, 242, 292, 335),
            cuesRu = listOf("Мягким прыжком колени чуть снаружи подмышек, руки слегка согнуты."), sanskrit = "адхо-бакасана", descriptionRu = "Из глубокого упора-горки мягким прыжком ставим колени к подмышечным впадинам — чуть снаружи, словно бёдрами цепляемся за плечи. Руки слегка согнуты, стопы поджаты.", descriptionEn = "From the deep downward plank, with a soft jump, place the knees at the armpits — just outside, as if hooking the thighs onto the shoulders. Arms slightly bent, feet tucked.",
            figure = FigureRef("bakadho", false)),
        Asana(id = "at_ekabaka", nameRu = "Ворона, одна нога назад", nameEn = "Crow, one leg back", pose = p(340, 20, 272, 270, 328, 150, 120, 352, 352, 0, 274, 272, 345),
            cuesRu = listOf("Левую ногу выпрямить вперёд."), sanskrit = "эка-пада-бакасана", descriptionRu = "Из стойки-сборки одна нога выпрямляется вперёд. Для равновесия поначалу можно слегка опираться большим пальцем опорной ноги.", descriptionEn = "From the tuck stance, one leg straightens forward. At first you may lightly support your balance with the big toe of the supporting leg.",
            figure = FigureRef("ekabaka", false)),
        Asana(id = "at_adhoeka", nameRu = "Ворона, нога вытянута назад", nameEn = "Crow, leg stretched back", pose = p(348, 5, 260, 280, 328, 150, 120, 170, 170, 175, 262, 282, 350),
            cuesRu = listOf("Левую ногу махом назад, тело ближе к горизонтали."), sanskrit = "адхо-мукха-эка-пада-бакасана", descriptionRu = "Не меняя положения опорного колена, сгибаем вытянутую ногу и мягким махом уводим её назад. Стараемся придать телу почти горизонтальное положение.", descriptionEn = "Without changing the position of the supporting knee, bend the extended leg and take it back with a soft swing. Try to bring the body almost horizontal.",
            figure = FigureRef("adhoeka", false)),
        Asana(id = "at_yozh", nameRu = "«Ежовый» наклон с полусборкой", nameEn = "“Hedgehog” bend with half tuck", pose = p(300, 200, 260, 275, 272, 270, 0, 150, 335, 330, 262, 277, 235),
            cuesRu = listOf("Правая стопа между ладоней, нога прямая; лоб к голени, спина круглая, левая пятка к ягодице."), sanskrit = null, descriptionRu = "Опорная нога ставится между ладоней и полностью выпрямляется. Вторая нога сгибается, пятка тянется к ягодице, колено — к середине спины. Лоб прижимается к прямой ноге и скользит к пупку, спина выгибается, как у свернувшегося ежа. Пресс сокращён до предела.", descriptionEn = "The supporting foot is placed between the palms and the leg straightens fully. The other leg bends, the heel reaching toward the buttock, the knee toward the middle of the back. The forehead presses to the straight leg and slides toward the navel, the back rounds like a curled-up hedgehog. Abs contracted to the limit.",
            figure = FigureRef("yozh", false)),
        Asana(id = "at_pnakup", nameRu = "Полупрогиб в вытянутом наклоне с левой ногой вверху", nameEn = "Half arch in the extended bend, left leg on top", pose = p(280, 45, 298, 298, 272, 270, 0, 130, 130, 140, 300, 300, 345),
            cuesRu = listOf("Прогиб в наклоне, левая нога назад-вверх."), sanskrit = null, descriptionRu = "Полупрогиб в вытянутом наклоне на одной ноге: ладони на полу, спина прогибается, а свободная нога одновременно тянется как можно дальше назад-вверх.", descriptionEn = "Half arch in the extended bend on one leg: palms on the floor, the back arches while the free leg reaches as far back and up as possible.",
            figure = FigureRef("pnakup", false)),
        Asana(id = "at_urdhvaeka", nameRu = "Вытянутый наклон с левой ногой вверху", nameEn = "Extended bend, left leg on top", pose = p(314, 242, 240, 210, 272, 270, 0, 112, 112, 120, 280, 275, 260),
            cuesRu = listOf("Правой рукой за лодыжку, левая нога выше, таз не поворачивать."), sanskrit = "урдхва-эка-падоттанасана", descriptionRu = "Одной рукой держим лодыжку опорной ноги, другой упираемся в пол. Свободная нога тянется всё выше вверх, подбородок скользит по опорной ноге к стопе. Пупок к бедру, седалищные кости вверх, таз не поворачивается.", descriptionEn = "One hand holds the ankle of the supporting leg, the other presses into the floor. The free leg reaches ever higher, the chin slides along the supporting leg toward the foot. Navel to the thigh, sitting bones up, the pelvis does not turn.",
            figure = FigureRef("urdhvaeka", false)),
        Asana(id = "at_povtaz", nameRu = "Вытянутый наклон с поворотом таза", nameEn = "Extended bend with pelvic turn", pose = p(314, 245, 285, 275, 272, 270, 0, 95, 330, 340, 288, 277, 262),
            cuesRu = listOf("Обе руки на пол, шейный замок, левую стопу махом за спину, раскрыть пах."), sanskrit = null, descriptionRu = "Обе руки на полу немного впереди опорной стопы, подбородок прижат — шейный замок. Поднятую ногу сгибаем и забрасываем стопу за спину, максимально разворачивая таз и раскрывая пах.", descriptionEn = "Both hands on the floor slightly in front of the supporting foot, chin pressed down — neck lock. Bend the raised leg and throw the foot behind the back, turning the pelvis as far as possible and opening the groin.",
            figure = FigureRef("povtaz", false)),
        Asana(id = "at_plechup", nameRu = "Плечевое вытягивание в наклоне с левой ногой вверху", nameEn = "Shoulder stretch in the bend, left leg on top", pose = p(314, 245, 55, 55, 272, 270, 0, 112, 112, 120, 53, 53, 262),
            cuesRu = listOf("Замок за спиной, руки рычагом тянут плечи вниз."), sanskrit = null, descriptionRu = "Таз возвращается в прямое положение, свободная нога снова прямо вверх. Прямые руки круговым махом заводим за спину в вывернутый замок и, используя их как рычаг, тянем плечи вниз.", descriptionEn = "The pelvis returns to a square position, the free leg goes straight up again. With a circular swing, bring the straight arms behind the back into a reversed lock and, using them as a lever, pull the shoulders down.",
            figure = FigureRef("plechup", false, hands = HandShape.LOCK)),
        Asana(id = "at_zhuravl", nameRu = "«Белый журавль в потоке янтарной росы»", nameEn = "“White crane in a stream of amber dew”", pose = p(15, 70, 200, 20, 270, 270, 0, 165, 80, 70, 202, 22, 40),
            cuesRu = listOf("Прогиб с высоко поднятой головой, носок левой ноги к макушке, кисти к бокам."), sanskrit = null, descriptionRu = "Балансируя на прямой опорной ноге, вытягиваем торс вперёд и прогибаемся, высоко поднимая голову; таз почти не поднимаем. Свободная нога сгибается, носок тянется к макушке. Со вдохом подтягиваем кисти к бокам — вдох «из земли» в солнечное сплетение.", descriptionEn = "Balancing on the straight supporting leg, extend the torso forward and arch, raising the head high; the pelvis barely rises. The free leg bends, the toes reaching toward the crown. On the inhale, pull the hands to the sides — an inhale “from the earth” into the solar plexus.",
            figure = FigureRef("zhuravl", false)),
        Asana(id = "at_tolk", nameRu = "«Толкнуть землю сердцами ладоней»", nameEn = "“Push the earth with the hearts of the palms”", pose = p(100, 95, 305, 305, 268, 270, 0, 0, 245, 290, 302, 302, 104),
            cuesRu = listOf("Выпрямиться с отклоном назад, колено вверх, руки вперёд-вниз, кисти на себя."), sanskrit = null, descriptionRu = "Быстро выпрямляемся с небольшим отклонением назад, поднимая колено свободной ноги и подтягивая стопу к промежности, носок оттянут. Руки резко выпрямляются вперёд-вниз, кисти на себя; жёсткий полный выдох «сквозь ладони», словно отталкиваемся от земли.", descriptionEn = "Quickly straighten up leaning slightly back, raising the knee of the free leg and drawing the foot toward the perineum, toes pointed. The arms sharply straighten forward and down, hands flexed toward you; a firm full exhale “through the palms”, as if pushing off the earth.",
            figure = FigureRef("tolk", false)),
        Asana(id = "at_prilech", nameRu = "«Прилечь на поток золота, текущий с той стороны»", nameEn = "“Lie down on the stream of gold flowing from the other side”", pose = p(120, 118, 245, 315, 265, 268, 0, 5, 5, 10, 248, 318, 128),
            cuesRu = listOf("Откинуться назад, левая нога горизонтально вперёд, носок оттянут."), sanskrit = null, descriptionRu = "Со вдохом откидываемся назад, свободная нога выпрямляется горизонтально вперёд, носок оттянут. Согнутыми пальцами рук будто подтягиваем под спину невидимый поток. Солнечное сплетение — самая высокая точка торса.", descriptionEn = "On the inhale, lean back, the free leg straightens horizontally forward, toes pointed. With bent fingers, as if drawing an invisible stream under the back. The solar plexus is the highest point of the torso.",
            figure = FigureRef("prilech", false)),
        Asana(id = "at_letstep", nameRu = "«Летящий шаг назад в золотой поток»", nameEn = "“Flying step back into the golden stream”", pose = p(92, 90, 320, 320, 310, 270, 0, 225, 225, 280, 318, 318, 92),
            cuesRu = listOf("Широкий шаг левой назад, руки вперёд-вниз."), sanskrit = null, descriptionRu = "С выдохом выпрямляемся и ставим свободную ногу как можно дальше назад — широкий шаг. Руки снова выпрямляются вперёд-вниз, «толкая землю» серединами ладоней.", descriptionEn = "On the exhale, straighten up and place the free leg as far back as possible — a wide step. The arms straighten forward and down again, “pushing the earth” with the centres of the palms.",
            figure = FigureRef("letstep", false)),
        Asana(id = "at_ring1", nameRu = "Одностороннее кольцо в широком шаге", nameEn = "One-sided ring in a wide step", pose = p(115, 175, 290, 300, 335, 270, 0, 265, 100, 130, 120, 175, 150),
            cuesRu = listOf("Левой рукой захватить левую стопу, прижать макушку к стопе."), sanskrit = "эка-пада-раджакапотасана", descriptionRu = "В широком шаге с коленом на полу сгибаем заднюю ногу. Одной рукой держимся за пол, другой из-за головы захватываем стопу и, вытягивая позвоночник, прогибаемся до касания макушкой стопы. Линии плеч и таза параллельны и перпендикулярны телу.", descriptionEn = "In the wide step with the knee on the floor, bend the back leg. One hand holds the floor, the other reaches from behind the head to grip the foot and, lengthening the spine, arch until the crown touches the foot. The lines of the shoulders and pelvis are parallel and perpendicular to the body.",
            figure = FigureRef("ring1", false)),
        Asana(id = "at_ring2", nameRu = "Одностороннее кольцо, стопа к правому плечу", nameEn = "One-sided ring, foot to the right shoulder", pose = p(105, 120, 290, 300, 335, 270, 0, 265, 100, 130, 150, 340, 128),
            cuesRu = listOf("Продеть голову под локоть, стопу к правому плечу сзади."), sanskrit = "эка-пада-раджакапотасана", descriptionRu = "Продолжение кольца: продеваем голову под локтем и подтягиваем стопу сзади к противоположному плечу.", descriptionEn = "Continuing the ring: thread the head under the elbow and draw the foot from behind to the opposite shoulder.",
            figure = FigureRef("ring2", false)),
        Asana(id = "at_skrut", nameRu = "Скручивание с растягиванием передней поверхности бедра", nameEn = "Twist with front-thigh stretch", pose = p(55, 25, 210, 250, 335, 270, 0, 265, 60, 80, 275, 275, 35),
            cuesRu = listOf("Правой рукой стопу к бедру, левое плечо за правое бедро, скрутиться."), sanskrit = null, descriptionRu = "Рукой нажимаем на подъём стопы задней ноги, прижимая её к тазу. Противоположное плечо заводим за переднее бедро, кисть на пол, и, отталкиваясь плечом, сильно скручиваем вытянутый позвоночник; голова до предела в сторону скрутки. Таз опускается вперёд-вниз, растягивая бедро.", descriptionEn = "Press the instep of the back foot with the hand, pressing it to the pelvis. Bring the opposite shoulder past the front thigh, hand on the floor, and, pushing with the shoulder, strongly twist the lengthened spine; the head turns to the limit in the direction of the twist. The pelvis lowers forward and down, stretching the thigh.",
            figure = FigureRef("skrut", false)),
        Asana(id = "at_cring1", nameRu = "Перекрёстное кольцо в широком шаге", nameEn = "Cross ring in a wide step", pose = p(115, 175, 120, 175, 335, 270, 0, 265, 100, 130, 290, 300, 150),
            cuesRu = listOf("Захватить левую стопу правой рукой, макушка к стопе."), sanskrit = null, descriptionRu = "Перекрёстное кольцо: заднюю стопу из-за головы захватываем противоположной рукой и мышцами спины прижимаем макушку к стопе. Таз и плечевой пояс выравниваем.", descriptionEn = "Cross ring: grip the back foot from behind the head with the opposite hand and, using the back muscles, press the crown to the foot. Level the pelvis and shoulder girdle.",
            figure = FigureRef("cring1", false)),
        Asana(id = "at_cring2", nameRu = "Перекрёстное кольцо, стопа к левому плечу", nameEn = "Cross ring, foot to the left shoulder", pose = p(105, 120, 150, 340, 335, 270, 0, 265, 100, 130, 290, 300, 128),
            cuesRu = listOf("Голова продевается под локоть, стопа подтягивается сзади к плечу той же стороны, что и нога"), sanskrit = null, descriptionRu = "Голова продевается под локоть, стопа подтягивается сзади к плечу той же стороны, что и нога.", descriptionEn = "The head threads under the elbow, the foot is drawn from behind to the shoulder on the same side as the leg.",
            figure = FigureRef("cring2", false)),
        Asana(id = "at_quad", nameRu = "Предельное растягивание передней поверхности бедра", nameEn = "Maximal front-thigh stretch", pose = p(25, 0, 300, 330, 335, 270, 0, 265, 75, 90, 190, 265, 5),
            cuesRu = listOf("Пятку к тазобедренному, торс на правое бедро."), sanskrit = null, descriptionRu = "Рукой той же стороны сильно нажимаем на пальцы и подъём задней ноги, прижимая пятку сбоку к тазобедренному суставу. Второй рукой опираемся на переднее колено, затем ложимся торсом на переднее бедро и ещё сильнее толкаем пятку вниз.", descriptionEn = "With the same-side hand, press firmly on the toes and instep of the back leg, pressing the heel from the side to the hip joint. The other hand rests on the front knee, then lay the torso on the front thigh and push the heel down even harder.",
            figure = FigureRef("quad", false)),
        Asana(id = "at_quadbend", nameRu = "Предельное растягивание бедра с прогибом", nameEn = "Maximal thigh stretch with arch", pose = p(105, 145, 305, 305, 335, 270, 0, 265, 75, 90, 190, 265, 130),
            cuesRu = listOf("Оттолкнуться от бедра и прогнуться назад."), sanskrit = null, descriptionRu = "Отталкиваясь рукой от переднего бедра, вытягиваем позвоночник и прогибаемся назад, продолжая давить на стопу задней ноги. Таз опускается, промежность и передняя поверхность бедра растягиваются ещё больше.", descriptionEn = "Pushing off the front thigh with the hand, lengthen the spine and arch back, continuing to press on the back foot. The pelvis lowers, the perineum and the front of the thigh stretch even more.",
