        Asana(id = "at_verb1", nameRu = "Вытянутый односторонний верхний верблюд", nameEn = "Extended one-sided upper camel", pose = p(345, 82, 105, 205, 150, 120, 120, 269, 180, 180, 272, 272, 55),
